"""Arabic names of the books (kutub) of each collection, by the book number
used in the fawazahmed0 hadith-api, which only gives English names. These
are the customary kitab titles of each work."""


def _t(names):
    return {i: "كتاب " + n for i, n in enumerate(names.split("|"), 1)}


